import javafx.geometry.*;import java.util.*;import ru.bccontrol.sedonastudio.ui.WireRouter;
public class RoutingBenchmark {
 public static void main(String[] args){List<Bounds> boxes=new ArrayList<>();for(int i=0;i<100;i++){boxes.add(new BoundingBox(60,60+i*72,220,48));boxes.add(new BoundingBox(720,60+i*72,220,48));}long[] times=new long[7];for(int iteration=0;iteration<9;iteration++){WireRouter router=new WireRouter(boxes,1200,7600);long begin=System.nanoTime();for(int i=0;i<100;i++){Bounds a=boxes.get(i*2),b=boxes.get(i*2+1);Point2D from=new Point2D(a.getMaxX()-12,a.getMinY()+24.25),to=new Point2D(b.getMinX()+12,b.getMinY()+24.25);List<Point2D> route=router.route(from,to,a,b);if(route.size()<2||!route.get(0).equals(from)||!route.get(route.size()-1).equals(to))throw new AssertionError("Missing/exact-end route");}if(iteration>=2)times[iteration-2]=System.nanoTime()-begin;}Arrays.sort(times);System.out.println("{\"medianMs\":"+times[3]/1e6+",\"routes\":100,\"cards\":200,\"measuredRuns\":7,\"warmupRuns\":2}");}
}
